package me.eiakoji.eip.routing;

import java.time.Duration;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/**
 * Production-grade Concurrent Aggregator with TTL-based memory eviction.
 * Accumulates split items by correlationId until all items arrive or timeout expires.
 */
public final class ConcurrentAggregator<T> implements AutoCloseable {

    public record SplitItem<T>(
        UUID correlationId,
        int sequenceNumber,
        int sequenceSize,
        T payload,
        Instant receivedAt
    ) {}

    public record AggregatedBatch<T>(
        UUID correlationId,
        List<T> items,
        boolean complete,
        Duration processingTime
    ) {}

    private static final class Accumulator<T> {
        final UUID correlationId;
        final int expectedSize;
        final Instant createdAt;
        final Map<Integer, T> items = new ConcurrentSkipListMap<>();

        Accumulator(UUID correlationId, int expectedSize) {
            this.correlationId = correlationId;
            this.expectedSize = expectedSize;
            this.createdAt = Instant.now();
        }

        boolean isComplete() {
            return items.size() >= expectedSize;
        }

        AggregatedBatch<T> buildBatch(boolean complete) {
            return new AggregatedBatch<>(
                correlationId,
                List.copyOf(items.values()),
                complete,
                Duration.between(createdAt, Instant.now())
            );
        }
    }

    private final ConcurrentMap<UUID, Accumulator<T>> buffers = new ConcurrentHashMap<>();
    private final Duration timeout;
    private final Consumer<AggregatedBatch<T>> onCompleteConsumer;
    private final Consumer<AggregatedBatch<T>> onTimeoutConsumer;
    private final ScheduledExecutorService reaper;

    public ConcurrentAggregator(
        Duration timeout,
        Consumer<AggregatedBatch<T>> onCompleteConsumer,
        Consumer<AggregatedBatch<T>> onTimeoutConsumer
    ) {
        this.timeout = Objects.requireNonNull(timeout);
        this.onCompleteConsumer = Objects.requireNonNull(onCompleteConsumer);
        this.onTimeoutConsumer = Objects.requireNonNull(onTimeoutConsumer);

        this.reaper = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = Thread.ofVirtual().name("aggregator-reaper").unstarted(r);
            t.setDaemon(true);
            return t;
        });

        long intervalMs = Math.max(100, timeout.toMillis() / 2);
        this.reaper.scheduleAtFixedRate(this::evictExpiredBuffers, intervalMs, intervalMs, TimeUnit.MILLISECONDS);
    }

    public void accept(SplitItem<T> item) {
        Accumulator<T> acc = buffers.computeIfAbsent(
            item.correlationId(),
            k -> new Accumulator<>(item.correlationId(), item.sequenceSize())
        );

        acc.items.put(item.sequenceNumber(), item.payload());

        if (acc.isComplete()) {
            if (buffers.remove(item.correlationId(), acc)) {
                onCompleteConsumer.accept(acc.buildBatch(true));
            }
        }
    }

    private void evictExpiredBuffers() {
        Instant now = Instant.now();
        for (Map.Entry<UUID, Accumulator<T>> entry : buffers.entrySet()) {
            Accumulator<T> acc = entry.getValue();
            if (Duration.between(acc.createdAt, now).compareTo(timeout) > 0) {
                if (buffers.remove(entry.getKey(), acc)) {
                    onTimeoutConsumer.accept(acc.buildBatch(false));
                }
            }
        }
    }

    @Override
    public void close() {
        reaper.shutdown();
        try {
            if (!reaper.awaitTermination(2, TimeUnit.SECONDS)) {
                reaper.shutdownNow();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}
